@Composable
fun ProfileScreen() {
    Scaffold(
        bottomBar = { BottomNavBar() }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .padding(horizontal = 24.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // Título "Perfil" alineado a la izquierda
            Text(
                text = "Perfil",
                style = MaterialTheme.typography.headlineMedium,
                fontWeight = FontWeight.Bold,
                modifier = Modifier
                    .align(Alignment.Start)
                    .padding(top = 16.dp, bottom = 24.dp)
            )

            Spacer(modifier = Modifier.height(16.dp))

            // Header con avatar, nombre y email
            ProfileHeader(
                userName = "Juan Pérez",
                userEmail = "juan.perez@email.com"
            )

            Spacer(modifier = Modifier.height(32.dp))

            // Opción de editar perfil
            ProfileMenuItem(
                icon = Icons.Default.Edit,
                text = "Editar Perfil",
                onClick = { /* TODO: Navegar a editar perfil */ }
            )

            Spacer(modifier = Modifier.height(8.dp))

            // Opción de configuración (nuevo)
            ProfileMenuItem(
                icon = Icons.Default.Settings,
                text = "Configuración",
                onClick = { /* TODO: Navegar a configuración */ }
            )

            Spacer(modifier = Modifier.weight(1f))

            // Botón de cerrar sesión
            LogoutButton(
                onClick = { /* TODO: Cerrar sesión */ }
            )

            Spacer(modifier = Modifier.height(16.dp))
        }
    }
}

